with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__PMASTERPOLICYNUMBER))) as HUB_POLICY_HK
        , cast(null as varchar) as INTERMEDIARY_REFERENCE
        , cast(null as varchar) as IMD_CODE
        , cast(null as varchar) as COMMISSION_RATE
        , cast(null as varchar) as SUB_IMD_CODE
        , cast(null as varchar) as COMMISSION_AMOUNT
        , 'BJAZ_GENERIC_LOADER_LOG_TABLE' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_generic_loader_log_table') }}
    where (nullif(trim(PMASTERPOLICYNUMBER),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , cast(null as varchar) as INTERMEDIARY_REFERENCE
        , IMD_CODE as IMD_CODE
        , cast(null as varchar) as COMMISSION_RATE
        , cast(null as varchar) as SUB_IMD_CODE
        , cast(null as varchar) as COMMISSION_AMOUNT
        , 'BJAZ_PMSBY_DATA_WEB_SERVICE' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_pmsby_data_web_service') }}
    where (nullif(trim(POLICY_REF),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , cast(null as varchar) as INTERMEDIARY_REFERENCE
        , cast(null as varchar) as IMD_CODE
        , COMMISION as COMMISSION_RATE
        , cast(null as varchar) as SUB_IMD_CODE
        , cast(null as varchar) as COMMISSION_AMOUNT
        , 'BJAZ_ENROLL_SCR_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_scr_dtls') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , coalesce(nullif(trim(INTERMEDIARY_CODE), ''), '') as INTERMEDIARY_REFERENCE
        , INTERMEDIARY_CODE as IMD_CODE
        , SUB_AGENT_COMM_RATE as COMMISSION_RATE
        , SUB_AGENT_CODE as SUB_IMD_CODE
        , SUB_AGENT_COMM_AMT as COMMISSION_AMOUNT
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , coalesce(nullif(trim(MAIN_AGENT_CODE), ''), '') as INTERMEDIARY_REFERENCE
        , MAIN_AGENT_CODE as IMD_CODE
        , SUB_AGENT_COMM_RATE as COMMISSION_RATE
        , SUB_AGENT_CODE as SUB_IMD_CODE
        , SUB_AGENT_COMM_AMT as COMMISSION_AMOUNT
        , 'BJAZ_POLICY_BASES_EXTN' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_bases_extn') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
),

resolved as (
    select
        HUB_POLICY_HK,
        INTERMEDIARY_REFERENCE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then IMD_CODE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then IMD_CODE end)) as IMD_CODE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then COMMISSION_RATE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then COMMISSION_RATE end)) as COMMISSION_RATE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then SUB_IMD_CODE end) as SUB_IMD_CODE,
        max(case when SOURCE_RUN = 'opus_health_delta3' then COMMISSION_AMOUNT end) as COMMISSION_AMOUNT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK, INTERMEDIARY_REFERENCE
),

hashed as (
    select
        *,
        case when INTERMEDIARY_REFERENCE is not null or IMD_CODE is not null or COMMISSION_RATE is not null or SUB_IMD_CODE is not null or COMMISSION_AMOUNT is not null
                     then md5(upper(coalesce(cast(INTERMEDIARY_REFERENCE as varchar), '') || '|' || coalesce(cast(IMD_CODE as varchar), '') || '|' || coalesce(cast(COMMISSION_RATE as varchar), '') || '|' || coalesce(cast(SUB_IMD_CODE as varchar), '') || '|' || coalesce(cast(COMMISSION_AMOUNT as varchar), '')))
                end as SAT_POLICY_INTERMEDIARY_SPLIT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_INTERMEDIARY_SPLIT_HASHDIFF is not null
